"""Demo-owned item contract and committed semantic effect evidence."""
import json
import re
from fastapi import Depends, Request
from fastapi.responses import JSONResponse
from opentelemetry import trace
from sqlalchemy.exc import IntegrityError, SQLAlchemyError
from .items import ItemStore, get_item_store, determine_effect
from . import items as item_logic


def validate(value):
    return (type(value) is dict and set(value) == {"id", "name"}
            and type(value["id"]) is int and 1 <= value["id"] <= 2147483647
            and type(value["name"]) is str
            and re.fullmatch(r"[A-Za-z0-9_-]{1,80}", value["name"]) is not None)


def register(app):
    @app.middleware("http")
    async def identify(request, call_next):
        trace.get_current_span().set_attribute("demo.request.shadow", request.headers.get("x-mobilis-shadow") == "true")
        response = await call_next(request)
        response.headers["X-Served-By"] = "legacy"
        return response

    @app.get("/items")
    def items(store: ItemStore = Depends(get_item_store)):
        try:
            return store.list_items()
        except SQLAlchemyError:
            return JSONResponse({"error": "database unavailable"}, status_code=503)

    @app.post("/items")
    async def create(request: Request, store: ItemStore = Depends(get_item_store)):
        try:
            value = json.loads((await request.body()).decode("utf-8"))
        except (ValueError, UnicodeError):
            value = None
        if not validate(value):
            return JSONResponse({"error": "invalid item"}, status_code=400)
        effect = determine_effect(value)
        with trace.get_tracer("items").start_as_current_span("items.write") as span:
            try:
                store.commit(effect)
            except IntegrityError:
                return JSONResponse({"error": "item exists"}, status_code=409)
            except SQLAlchemyError:
                return JSONResponse({"error": "database unavailable"}, status_code=503)
            # Evidence represents a completed transaction, never an attempted one.
            span.set_attributes(item_logic.effect_attributes(effect,
                shadow=request.headers.get("x-mobilis-shadow") == "true", committed=True))
        return JSONResponse(value, status_code=201)

"""The demo's database collaborator and semantic effect representation."""
import json
import re
from sqlalchemy import event, select, text
from sqlalchemy.engine import Engine
from sqlalchemy.exc import SQLAlchemyError
from opentelemetry import trace
from .database import get_session
from .models import Item


@event.listens_for(Engine, "after_cursor_execute")
def record_executed_sql(connection, cursor, statement, parameters, context, executemany):
    # Observe the driver's real SQL and bindings, rather than a business-logic
    # description that could remain unchanged when the ORM query drifts.
    if re.fullmatch(r"\s*(?:(?:BEGIN|COMMIT|ROLLBACK)|SET\s+LOCAL\s+application_name\s*=\s*'(?:legacy|candidate)')\s*;?\s*",
                    statement, flags=re.IGNORECASE):
        return
    with trace.get_tracer("items").start_as_current_span("items.sql") as span:
        span.set_attributes({"demo.sql.text": statement,
                             "demo.sql.parameters": json.dumps(parameters),
                             "demo.sql.executed": True,
                             "demo.sql.executemany": executemany})


def determine_effect(value):
    return {"operation": "insert", "table": "items", "values": dict(value)}


def effect_attributes(effect, *, shadow, committed):
    return {"demo.write.mode": "shadow" if shadow else "actual",
            "demo.request.shadow": shadow, "demo.write.committed": committed,
            "db.operation.name": "INSERT", "db.collection.name": "items",
            "demo.write.effect": json.dumps(effect, sort_keys=True)}


class ItemStore:
    def __init__(self, sessions=get_session):
        self.sessions = sessions

    def list_items(self):
        with self.sessions() as session:
            return [{"id": item.id, "name": item.name}
                    for item in session.scalars(select(Item).order_by(Item.id))]

    def commit(self, effect):
        with self.sessions() as session:
            try:
                session.execute(text("SET LOCAL application_name = 'legacy'"))
                session.add(Item(**effect["values"]))
                session.commit()
            except SQLAlchemyError:
                session.rollback()
                raise


def get_item_store():
    return ItemStore()

package app

import (
	"context"
	"encoding/json"
	"errors"
	"io"
	"log"
	"net/http"
	"regexp"

	"github.com/jackc/pgx/v5/pgconn"
	"go.opentelemetry.io/otel"
	"go.opentelemetry.io/otel/attribute"
	"go.opentelemetry.io/otel/trace"
)

type item struct {
	ID   int32  `json:"id"`
	Name string `json:"name"`
}

// One semantic effect is computed before the commit decision, and supplies both
// the database values and telemetry. No separate shadow business logic exists.
type itemEffect struct {
	Operation string `json:"operation"`
	Table     string `json:"table"`
	Values    item   `json:"values"`
}

func determineEffect(value item) itemEffect {
	return itemEffect{Operation: "insert", Table: "items", Values: value}
}

// The reserved header is trusted only behind the generated gateway: backend
// HTTP ports are unpublished, and ingress strips caller copies before routing.
func isShadowRequest(r *http.Request) bool {
	values := r.Header.Values("X-Mobilis-Shadow")
	return len(values) == 1 && values[0] == "true"
}

func recordRequestContext(r *http.Request) bool {
	shadow := isShadowRequest(r)
	trace.SpanFromContext(r.Context()).SetAttributes(attribute.Bool("demo.request.shadow", shadow))
	return shadow
}

// This is the only divergence: shadow skips the same computed effect's commit.
func commitItem(ctx context.Context, store itemStore, effect itemEffect, shadow bool) (bool, error) {
	if shadow {
		statement, parameters := insertPlan(effect)
		_, span := sqlEvidence(ctx, statement, parameters, false)
		span.End()
		return false, nil
	}
	err := store.Commit(ctx, effect)
	return err == nil, err
}

func effectAttributes(effect itemEffect, shadow, committed bool) []attribute.KeyValue {
	encoded, _ := json.Marshal(effect)
	mode := "actual"
	if shadow {
		mode = "shadow"
	}
	return []attribute.KeyValue{
		attribute.String("demo.write.mode", mode), attribute.Bool("demo.request.shadow", shadow),
		attribute.Bool("demo.write.committed", committed), attribute.String("db.operation.name", "INSERT"),
		attribute.String("db.collection.name", "items"), attribute.String("demo.write.effect", string(encoded)),
	}
}

func reply(w http.ResponseWriter, status int, value any) {
	w.Header().Set("Content-Type", "application/json")
	w.Header().Set("X-Served-By", "candidate")
	w.WriteHeader(status)
	if err := json.NewEncoder(w).Encode(value); err != nil {
		log.Printf("response: %v", err)
	}
}

func register(mux *http.ServeMux, deps Dependencies) {
	registerItems(mux, postgresItems{deps.DB}, otel.Tracer("items"))
}

func registerItems(mux *http.ServeMux, store itemStore, tracer trace.Tracer) {
	mux.HandleFunc("GET /items", func(w http.ResponseWriter, r *http.Request) {
		recordRequestContext(r)
		items, err := store.List(r.Context())
		if err != nil {
			if errors.Is(err, errInvalidRows) {
				reply(w, 500, map[string]string{"error": "database error"})
			} else {
				reply(w, 503, map[string]string{"error": "database unavailable"})
			}
			return
		}
		reply(w, 200, items)
	})
	mux.HandleFunc("POST /items", func(w http.ResponseWriter, r *http.Request) {
		shadow := recordRequestContext(r)
		// Decode the exact field set and types, without coercion or unknown fields.
		var fields map[string]json.RawMessage
		decoder := json.NewDecoder(r.Body)
		var value item
		invalid := decoder.Decode(&fields) != nil || len(fields) != 2
		if !invalid {
			invalid = string(fields["id"]) == "null" || string(fields["name"]) == "null" ||
				json.Unmarshal(fields["id"], &value.ID) != nil || json.Unmarshal(fields["name"], &value.Name) != nil
		}
		var extra any
		if invalid || decoder.Decode(&extra) != io.EOF || value.ID < 1 || !regexp.MustCompile(`^[A-Za-z0-9_-]{1,80}$`).MatchString(value.Name) {
			reply(w, 400, map[string]string{"error": "invalid item"})
			return
		}
		effect := determineEffect(value)
		ctx, span := tracer.Start(r.Context(), "items.write")
		defer span.End()
		committed, err := commitItem(ctx, store, effect, shadow)
		if err != nil {
			var pgerr *pgconn.PgError
			if errors.As(err, &pgerr) && pgerr.Code == "23505" {
				reply(w, 409, map[string]string{"error": "item exists"})
				return
			}
			reply(w, 503, map[string]string{"error": "database unavailable"})
			return
		}
		span.SetAttributes(effectAttributes(effect, shadow, committed)...)

		reply(w, 201, value)
	})
}

package app

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"net/http"
	"net/http/httptest"
	"reflect"
	"strings"
	"testing"

	"github.com/jackc/pgx/v5/pgconn"
	"go.opentelemetry.io/contrib/instrumentation/net/http/otelhttp"
	"go.opentelemetry.io/otel/attribute"
	"go.opentelemetry.io/otel/propagation"
	sdktrace "go.opentelemetry.io/otel/sdk/trace"
	"go.opentelemetry.io/otel/sdk/trace/tracetest"
)

var sample = item{ID: 42, Name: "foo"}
var expectedEffect = itemEffect{Operation: "insert", Table: "items", Values: sample}

// Implements the real production interface. Unplanned calls fail immediately;
// cleanup also rejects missing calls. No database, network or SDK mocks exist.
type validatingStore struct {
	t                  *testing.T
	wantReads          int
	expected           *itemEffect
	items              []item
	readErr, commitErr error
	reads, commits     int
}

var _ itemStore = (*validatingStore)(nil)

func (store *validatingStore) List(ctx context.Context) ([]item, error) {
	store.t.Helper()
	store.reads++
	if ctx == nil || store.reads > store.wantReads {
		store.t.Fatal("unexpected List call")
	}
	return store.items, store.readErr
}
func (store *validatingStore) Commit(ctx context.Context, effect itemEffect) error {
	store.t.Helper()
	store.commits++
	if ctx == nil || store.expected == nil || store.commits != 1 || effect != *store.expected {
		store.t.Fatalf("unexpected Commit(%+v), count=%d", effect, store.commits)
	}
	return store.commitErr
}
func newStore(t *testing.T) *validatingStore {
	store := &validatingStore{t: t}
	t.Cleanup(func() {
		wantCommits := 0
		if store.expected != nil {
			wantCommits = 1
		}
		if store.commits != wantCommits || store.reads != store.wantReads {
			t.Fatalf("calls: reads=%d/%d commits=%d/%d", store.reads, store.wantReads, store.commits, wantCommits)
		}
	})
	return store
}

func testHandler(t *testing.T, store itemStore) (http.Handler, *tracetest.SpanRecorder) {
	recorder := tracetest.NewSpanRecorder()
	provider := sdktrace.NewTracerProvider(sdktrace.WithSpanProcessor(recorder))
	t.Cleanup(func() {
		if err := provider.Shutdown(context.Background()); err != nil {
			t.Fatal(err)
		}
	})
	mux := http.NewServeMux()
	registerItems(mux, store, provider.Tracer("items"))
	return otelhttp.NewHandler(mux, "http", otelhttp.WithTracerProvider(provider),
		otelhttp.WithPropagators(propagation.TraceContext{})), recorder
}

func request(handler http.Handler, method, body string, marker []string) *httptest.ResponseRecorder {
	r := httptest.NewRequest(method, "/items", strings.NewReader(body))
	r.Header["X-Mobilis-Shadow"] = marker
	r.Header.Set("traceparent", "00-11111111111111111111111111111111-2222222222222222-01")
	response := httptest.NewRecorder()
	handler.ServeHTTP(response, r)
	return response
}

func checkResponse(t *testing.T, response *httptest.ResponseRecorder, status int, body any) {
	t.Helper()
	var actual any
	if err := json.Unmarshal(response.Body.Bytes(), &actual); err != nil {
		t.Fatal(err)
	}
	encoded, err := json.Marshal(body)
	if err != nil {
		t.Fatal(err)
	}
	var expected any
	if err := json.Unmarshal(encoded, &expected); err != nil {
		t.Fatal(err)
	}
	if response.Code != status || !reflect.DeepEqual(actual, expected) || response.Header().Get("Content-Type") != "application/json" {
		t.Fatalf("response %d %s %v, want %d %s", response.Code, response.Body, response.Header(), status, encoded)
	}
	if response.Header().Get("X-Served-By") != "candidate" {
		t.Fatal("candidate response identity missing")
	}
}

func attributes(values []attribute.KeyValue) map[string]any {
	result := make(map[string]any)
	for _, value := range values {
		result[string(value.Key)] = value.Value.AsInterface()
	}
	return result
}

func TestHealthNeedsNoInfrastructure(t *testing.T) {
	response := httptest.NewRecorder()
	Handler(Dependencies{}).ServeHTTP(response, httptest.NewRequest("GET", "/health", nil))
	if response.Code != 200 || response.Body.String() != `{"status":"ok"}` || response.Header().Get("Content-Type") != "application/json" {
		t.Fatal(response)
	}
}

func TestItemReadContract(t *testing.T) {
	for _, values := range [][]item{{}, {{ID: 1, Name: "example"}, sample}} {
		t.Run(fmt.Sprint(values), func(t *testing.T) {
			store := newStore(t)
			store.wantReads, store.items = 1, values
			handler, _ := testHandler(t, store)
			checkResponse(t, request(handler, "GET", "", nil), 200, values)
		})
	}
}

func TestReadDependencyFailures(t *testing.T) {
	for _, tc := range []struct {
		err     error
		status  int
		message string
	}{
		{errors.New("offline"), 503, "database unavailable"},
		{errors.Join(errInvalidRows, errors.New("scan failed")), 500, "database error"},
	} {
		t.Run(tc.message, func(t *testing.T) {
			store := newStore(t)
			store.wantReads, store.readErr = 1, tc.err
			handler, _ := testHandler(t, store)
			checkResponse(t, request(handler, "GET", "", nil), tc.status, map[string]string{"error": tc.message})
		})
	}
}

func TestShadowRequestContext(t *testing.T) {
	for _, tc := range []struct {
		values []string
		shadow bool
	}{
		{nil, false}, {[]string{"true"}, true}, {[]string{"false"}, false},
		{[]string{"true", "true"}, false}, {[]string{"true,false"}, false},
		{[]string{"TRUE"}, false}, {[]string{" true"}, false}, {[]string{"1"}, false}, {[]string{""}, false},
	} {
		t.Run(fmt.Sprint(tc.values), func(t *testing.T) {
			r := httptest.NewRequest("POST", "/items", nil)
			r.Header["X-Mobilis-Shadow"] = tc.values
			if got := isShadowRequest(r); got != tc.shadow {
				t.Fatalf("shadow=%v", got)
			}
			store := newStore(t)
			if !tc.shadow {
				store.expected = &expectedEffect
			}
			handler, recorder := testHandler(t, store)
			checkResponse(t, request(handler, "POST", `{"id":42,"name":"foo"}`, tc.values), 201, sample)
			checkEffectEvidence(t, recorder, tc.shadow, expectedEffect)
		})
	}
}

func checkEffectEvidence(t *testing.T, recorder *tracetest.SpanRecorder, shadow bool, expected itemEffect) {
	t.Helper()
	effects, servers, plans := 0, 0, 0
	for _, span := range recorder.Ended() {
		if span.SpanContext().TraceID().String() != "11111111111111111111111111111111" {
			t.Fatal("request context was lost")
		}
		attrs := attributes(span.Attributes())
		if span.Name() == "items.write" {
			effects++
			var effect itemEffect
			if err := json.Unmarshal([]byte(attrs["demo.write.effect"].(string)), &effect); err != nil {
				t.Fatal(err)
			}
			mode := "actual"
			if shadow {
				mode = "shadow"
			}
			if effect != expected || attrs["demo.request.shadow"] != shadow || attrs["demo.write.committed"] != !shadow || attrs["demo.write.mode"] != mode || attrs["db.operation.name"] != "INSERT" || attrs["db.collection.name"] != "items" {
				t.Fatal(attrs)
			}
		} else if span.Name() == "http" {
			servers++
			if attrs["demo.request.shadow"] != shadow {
				t.Fatal(attrs)
			}
		} else if span.Name() == "items.sql" {
			plans++
			bindings, err := json.Marshal([]any{expected.Values.ID, expected.Values.Name})
			if err != nil {
				t.Fatal(err)
			}
			if !shadow || attrs["demo.sql.executed"] != false || attrs["demo.sql.text"] != "INSERT INTO items (id, name) VALUES ($1, $2)" || attrs["demo.sql.parameters"] != string(bindings) {
				t.Fatal("shadow SQL plan drift", attrs)
			}
		}
	}
	if effects != 1 || servers != 1 {
		t.Fatalf("effects=%d servers=%d", effects, servers)
	}
	if (shadow && plans != 1) || (!shadow && plans != 0) {
		t.Fatalf("unexpected shadow SQL plans: %d", plans)
	}
}

func TestShadowSkipsOnlyCommitBoundary(t *testing.T) {
	effect := determineEffect(sample)
	if effect != expectedEffect {
		t.Fatal(effect)
	}
	// Retain the nil-collaborator proof: shadow cannot make ANY database call.
	committed, err := commitItem(context.Background(), nil, effect, true)
	if err != nil || committed {
		t.Fatalf("committed=%v err=%v", committed, err)
	}
	for _, shadow := range []bool{false, true} {
		store := newStore(t)
		if !shadow {
			store.expected = &expectedEffect
		}
		handler, recorder := testHandler(t, store)
		var marker []string
		if shadow {
			marker = []string{"true"}
		}
		checkResponse(t, request(handler, "POST", `{"id":42,"name":"foo"}`, marker), 201, sample)
		// Both executions independently report EXACTLY the effect asserted at commit.
		checkEffectEvidence(t, recorder, shadow, expectedEffect)
	}
}

func TestDeterministicEffectAttributes(t *testing.T) {
	for _, shadow := range []bool{false, true} {
		attrs := attributes(effectAttributes(determineEffect(sample), shadow, !shadow))
		if attrs["demo.write.effect"] != `{"operation":"insert","table":"items","values":{"id":42,"name":"foo"}}` {
			t.Fatal(attrs)
		}
		if attrs["demo.request.shadow"] != shadow || attrs["demo.write.committed"] != !shadow || attrs["db.operation.name"] != "INSERT" || attrs["db.collection.name"] != "items" {
			t.Fatal(attrs)
		}
	}
}

func TestShadowHandlerUsesNormalValidationAndEffect(t *testing.T) {
	invalid := []string{"", "{", "null", "[]", "{}",
		`{"id":true,"name":"foo"}`, `{"id":1.0,"name":"foo"}`, `{"id":"42","name":"foo"}`,
		`{"id":null,"name":"foo"}`, `{"id":0,"name":"foo"}`, `{"id":-1,"name":"foo"}`,
		`{"id":2147483648,"name":"foo"}`, `{"id":42}`, `{"name":"foo"}`,
		`{"id":42,"name":null}`, `{"id":42,"name":12}`, `{"id":42,"name":""}`,
		`{"id":42,"name":"bad name"}`, `{"id":42,"name":"foo","extra":1}`,
		`{"id":42,"name":"foo"} {}`, "\xef\xbb\xbf" + `{"id":42,"name":"foo"}`,
		"\xff\xfe{\x00}", `{"id":42,"name":"é"}`, `{"id":42,"name":"` + strings.Repeat("x", 81) + `"}`}
	for _, shadow := range []bool{false, true} {
		for index, body := range invalid {
			t.Run(fmt.Sprintf("shadow=%v/input=%d", shadow, index), func(t *testing.T) {
				store := newStore(t)
				handler, recorder := testHandler(t, store)
				var marker []string
				if shadow {
					marker = []string{"true"}
				}
				checkResponse(t, request(handler, "POST", body, marker), 400, map[string]string{"error": "invalid item"})
				for _, span := range recorder.Ended() {
					if span.Name() == "items.write" {
						t.Fatal("invalid input produced an effect")
					}
				}
			})
		}
	}
}

func TestWriteBoundaries(t *testing.T) {
	for _, value := range []item{{ID: 1, Name: "A_-0"}, {ID: 2147483647, Name: strings.Repeat("x", 80)}} {
		for _, shadow := range []bool{false, true} {
			t.Run(fmt.Sprintf("%d/shadow=%v", value.ID, shadow), func(t *testing.T) {
				effect := itemEffect{Operation: "insert", Table: "items", Values: value}
				store := newStore(t)
				if !shadow {
					store.expected = &effect
				}
				handler, recorder := testHandler(t, store)
				encoded, _ := json.Marshal(value)
				var marker []string
				if shadow {
					marker = []string{"true"}
				}
				checkResponse(t, request(handler, "POST", string(encoded), marker), 201, value)
				checkEffectEvidence(t, recorder, shadow, effect)
			})
		}
	}
}

func TestWriteDependencyFailuresDoNotReportCommittedEffects(t *testing.T) {
	for _, tc := range []struct {
		err     error
		status  int
		message string
	}{
		{&pgconn.PgError{Code: "23505"}, 409, "item exists"},
		{errors.New("commit failed"), 503, "database unavailable"},
		{&pgconn.PgError{Code: "08006"}, 503, "database unavailable"},
	} {
		t.Run(tc.err.Error(), func(t *testing.T) {
			store := newStore(t)
			store.expected, store.commitErr = &expectedEffect, tc.err
			handler, recorder := testHandler(t, store)
			checkResponse(t, request(handler, "POST", `{"id":42,"name":"foo"}`, nil), tc.status, map[string]string{"error": tc.message})
			for _, span := range recorder.Ended() {
				if _, ok := attributes(span.Attributes())["demo.write.effect"]; ok {
					t.Fatal("failed commit reported as applied")
				}
			}
		})
	}
}

package app

import (
	"context"
	"encoding/json"
	"errors"
	"github.com/jackc/pgx/v5/pgxpool"
	"go.opentelemetry.io/otel/attribute"
	"go.opentelemetry.io/otel/trace"
)

// This interface is owned by the demo; the archetype still supplies ordinary pgx.
type itemStore interface {
	List(context.Context) ([]item, error)
	Commit(context.Context, itemEffect) error
}

type postgresItems struct{ db *pgxpool.Pool }

var _ itemStore = postgresItems{}
var errInvalidRows = errors.New("invalid item rows")

func insertPlan(effect itemEffect) (string, []any) {
	return "INSERT INTO items (id, name) VALUES ($1, $2)", []any{effect.Values.ID, effect.Values.Name}
}

func sqlEvidence(ctx context.Context, statement string, parameters []any, executed bool) (context.Context, trace.Span) {
	if parameters == nil {
		parameters = []any{}
	}
	encoded, _ := json.Marshal(parameters)
	return trace.SpanFromContext(ctx).TracerProvider().Tracer("items").Start(ctx, "items.sql", trace.WithAttributes(
		attribute.String("demo.sql.text", statement), attribute.String("demo.sql.parameters", string(encoded)),
		attribute.Bool("demo.sql.executed", executed), attribute.Bool("demo.sql.executemany", false)))
}

func (store postgresItems) List(ctx context.Context) ([]item, error) {
	statement := "SELECT id, name FROM items ORDER BY id"
	ctx, span := sqlEvidence(ctx, statement, nil, true)
	defer span.End()
	rows, err := store.db.Query(ctx, statement)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := make([]item, 0)
	for rows.Next() {
		var value item
		if err := rows.Scan(&value.ID, &value.Name); err != nil {
			return nil, errors.Join(errInvalidRows, err)
		}
		items = append(items, value)
	}
	if err := rows.Err(); err != nil {
		return nil, errors.Join(errInvalidRows, err)
	}
	return items, nil
}

func (store postgresItems) Commit(ctx context.Context, effect itemEffect) error {
	tx, err := store.db.Begin(ctx)
	if err != nil {
		return err
	}
	defer func() { _ = tx.Rollback(ctx) }()
	_, err = tx.Exec(ctx, "SET LOCAL application_name = 'candidate'")
	if err == nil {
		statement, parameters := insertPlan(effect)
		queryCtx, span := sqlEvidence(ctx, statement, parameters, true)
		_, err = tx.Exec(queryCtx, statement, parameters...)
		span.End()
	}
	if err == nil {
		err = tx.Commit(ctx)
	}
	return err
}

#!/usr/bin/env bash
# Sourced by every infrastructure-facing demo helper after changing directory.
export MOBILIS_ENV=${MOBILIS_ENV:-development}
case "$MOBILIS_ENV" in
  development) mobilis_dc=./dc_dev ;;
  test) mobilis_dc=./dc_test ;;
  production) mobilis_dc=./dc_prod ;;
  *) echo "MOBILIS_ENV must be development, test, or production (got: $MOBILIS_ENV)" >&2; exit 2 ;;
esac
dc() { "$mobilis_dc" "$@"; }
